test('preservation coverage classifies every current academy relation and exposes missing guards before disposal',async()=>{
 const f=await fixture();try{const coverage=(await f.pg.query<{relation_name:string;classification:string;delete_guard_present:boolean;truncate_guard_present:boolean}>('SELECT * FROM platform_private.academy_preservation_coverage ORDER BY relation_name')).rows,preserved=coverage.filter(r=>r.classification==='preserved_record'),exempt=coverage.filter(r=>r.classification==='operational_projection');console.log(JSON.stringify({check:'academy-preservation-current-schema',preservedRelations:preserved.length,operationalProjections:exempt.length}));assert.ok(preserved.length>300);assert.equal(exempt.length,9);assert.ok(preserved.every(r=>r.delete_guard_present&&r.truncate_guard_present));assert.deepEqual(exempt.map(r=>r.relation_name),['assignment_cities','assignment_classes','assignment_countries','assignment_hubs','assignment_people','assignment_regions','report_job_issue_backlog','role_assignments','role_permissions']);const policy=(await f.request('academies/'+f.a+'/retention')).body.data;assert.equal(policy.databasePreservationCoverage.preservedRelationCount,preserved.length);assert.equal(policy.databasePreservationCoverage.unprotectedRelationCount,0);assert.equal(policy.databasePreservationCoverage.identityAndExternalStorageIncluded,false);assert.equal(policy.deletionAuthorized,false);
 await f.pg.exec('ALTER TABLE public.countries DISABLE TRIGGER academy_preservation_delete');try{assert.equal((await f.request('academies/'+f.a+'/retention')).body.data.databasePreservationCoverage.unprotectedRelationCount,1);}finally{await f.pg.exec('ALTER TABLE public.countries ENABLE TRIGGER academy_preservation_delete');}await assert.rejects(f.pg.exec("UPDATE platform_private.preservation_exemptions SET reason='silently reclassified'"),/PLATFORM_HISTORY_IMMUTABLE/);
 }finally{await f.pg.close();}
});
