test('preservation bulk clearing is fenced against a newly recorded uncommitted hold',{skip:!process.env.TEST_DATABASE_URL},async()=>{
 const f=await fixture();const c=await f.pg.runtime!.connect();try{const target=(await f.pg.query<{relation_name:string}>("SELECT v.relation_name FROM platform_private.academy_preservation_coverage v JOIN pg_class c ON c.relname=v.relation_name JOIN pg_namespace n ON n.oid=c.relnamespace AND n.nspname='public' WHERE v.classification='preserved_record' AND NOT EXISTS(SELECT 1 FROM pg_constraint fk WHERE fk.contype='f' AND fk.confrelid=c.oid) ORDER BY v.relation_name LIMIT 1")).rows[0].relation_name;assert.match(target,/^[a-z_]+$/);await c.query('BEGIN');await c.query('SET LOCAL ROLE kavosh_platform_service');const hold=(await c.query<{result:any}>("SELECT platform_private.request($1,$2,'holds.create',$3,$4::jsonb) result",[f.owner.user,f.owner.session,randomUUID(),JSON.stringify({academyId:f.a,caseReference:'CONCURRENT-PRESERVATION',reason:'PRIVATE explicit preservation'})])).rows[0].result;assert.equal(hold.status,201);await f.pg.exec("BEGIN;SET LOCAL lock_timeout='150ms'");try{await assert.rejects(f.pg.exec('TRUNCATE public.'+target),(e:unknown)=>!!e&&typeof e==='object'&&'code'in e&&e.code==='55P03');}finally{await f.pg.exec('ROLLBACK');}const waiter=await f.pg.runtime!.connect();let pending:Promise<{error:unknown}>|undefined;try{const inheritedRole=(await waiter.query<{role:string}>('SELECT current_user role')).rows[0].role;console.log(JSON.stringify({check:'preservation-operator-fixture',inheritedRole,explicitOperatorReset:true}));await waiter.query('RESET ROLE');await waiter.query('BEGIN');await waiter.query("SET LOCAL lock_timeout='2s'");const pid=(await waiter.query<{pid:number}>('SELECT pg_backend_pid() pid')).rows[0].pid;pending=waiter.query('TRUNCATE public.'+target).then(()=>({error:null}),error=>({error}));let blocked=false;for(let i=0;i<100;i++){blocked=(await f.pg.query<{blocked:boolean}>("SELECT EXISTS(SELECT 1 FROM pg_locks WHERE pid=$1 AND locktype='advisory' AND NOT granted) blocked",[pid])).rows[0].blocked;if(blocked)break;await delay(5);}assert.equal(blocked,true,'The actual clearing statement must wait behind the uncommitted hold fence');await c.query('COMMIT');const result=await pending;assert.match(String(result.error),/ACADEMY_LEGAL_HOLD_ACTIVE/);}finally{await c.query('ROLLBACK');await pending;await waiter.query('ROLLBACK');waiter.release();}
 }finally{await c.query('ROLLBACK');c.release();await f.pg.close();}
});
