 await upgradeToCurrent(f.pg);assert.deepEqual(await snapshot(),before);assert.deepEqual((await f.pg.query(sql)).rows,authority);assert.deepEqual((await f.request('academies/'+f.a+'/legal-holds',{caseReference:input.caseReference,reason:input.reason},'master',key)).body,old.body);const policy=(await f.request('academies/'+f.a+'/retention')).body.data;assert.equal(policy.activeHoldCount,1);assert.equal(policy.databasePreservationCoverage.unprotectedRelationCount,0);assert.equal(policy.externalStorageHoldVerified,false);
