test('legal-hold workflow persists independent cases releases and exact retries without authorizing disposal',async()=>{
 const f=await fixture();try{const path='academies/'+f.a+'/legal-holds',policy='academies/'+f.a+'/retention',input={caseReference:'CASE-A',reason:'PRIVATE preservation basis'},key=randomUUID(),first=await f.request(path,input,'master',key);assert.equal(first.response.status,201,JSON.stringify(first.body));assert.equal(first.body.data.status,'active');assert.equal(first.body.data.scope,'entire_academy');assert.equal(first.body.deletionPerformed,false);assert.equal(first.body.deletionAuthorized,false);assert.equal(first.body.externalStorageHoldVerified,false);assert.equal(first.response.headers.get('cache-control'),'no-store');assert.deepEqual((await f.request(path,input,'master',key)).body,first.body);assert.equal((await f.request(path,{...input,reason:'Changed basis'},'master',key)).response.status,409);assert.equal((await f.request(path,input)).body.error.code,'PLATFORM_HOLD_ALREADY_ACTIVE');const second=await f.request(path,{...input,caseReference:'CASE-B'});assert.equal(second.response.status,201);assert.equal((await f.request(policy)).body.data.activeHoldCount,2);
 const release={expectedVersion:1,confirmAcademyId:f.a,reason:'PRIVATE reviewed resolution'},releaseKey=randomUUID(),released=await f.request(path+'/'+first.body.data.id+'/release',release,'master',releaseKey);assert.equal(released.response.status,200,JSON.stringify(released.body));assert.equal(released.body.data.version,2);assert.equal(released.body.data.status,'released');assert.deepEqual((await f.request(path+'/'+first.body.data.id+'/release',release,'master',releaseKey)).body,released.body);assert.equal((await f.request(path+'/'+first.body.data.id+'/release',release)).body.error.code,'PLATFORM_HOLD_ALREADY_RELEASED');assert.equal((await f.request(policy)).body.data.preservationRequired,true);assert.equal((await f.request(policy)).body.data.activeHoldCount,1);assert.equal((await f.request(path+'/'+first.body.data.id)).body.data.basis,input.reason);
 assert.equal((await f.request(path+'/'+second.body.data.id+'/release',release)).response.status,200);const after=(await f.request(policy)).body.data;assert.equal(after.preservationRequired,false);assert.equal(after.deletionAuthorized,false);assert.equal(after.statutoryRetentionEvaluated,false);const page=await f.request(path+'?limit=1');assert.ok(page.body.nextCursor);const next=await f.request(path+'?limit=1&after='+page.body.nextCursor);assert.equal(next.body.data.length,1);assert.notEqual(next.body.data[0].id,page.body.data[0].id);assert.equal(next.body.nextCursor,null);assert.equal((await f.pg.query("SELECT * FROM platform_private.audit_events WHERE action IN('platform.retention.hold.created','platform.retention.hold.released')")).rows.length,4);
 }finally{await f.pg.close();}
});
