test('cancellation intent has a native30-day clock and immutable withdrawal history without changing access or cancelling a replacement',async()=>{
 const f=await fixture();try{
  const path='academies/'+f.a+'/subscription/cancellations',input={expectedVersion:0,reason:'Synthetic cancellation intent'},schools=(await f.pg.query('SELECT * FROM public.academies ORDER BY id')).rows,key=randomUUID(),made=await f.request(path,input,'master',key);assert.equal(made.response.status,201,JSON.stringify(made.body));assert.equal(made.response.headers.get('cache-control'),'no-store');for(const k of ['schoolAccessChanged','cancellationPerformed','deletionPerformed','chargesPerformed'])assert.equal(made.body[k],false);
  const first=made.body.data;assert.equal(first.status,'pending');assert.equal(first.version,1);assert.equal(first.requestedSubscriptionVersion,0);assert.equal(Date.parse(first.reviewAfter)-Date.parse(first.requestedAt),30*86400000);assert.deepEqual((await f.request(path,input,'master',key)).body,made.body);
  assert.equal((await f.request(path,input)).response.status,409);assert.equal((await f.request(path+'/'+first.id)).body.data.id,first.id);assert.equal((await f.request(path)).body.data.length,1);
  const clock=(await f.pg.query<any>("SELECT extract(epoch FROM review_after-requested_at)::integer seconds,requested_at<=clock_timestamp() recorded FROM platform_private.school_cancellation_requests WHERE id=$1",[first.id])).rows[0];assert.equal(clock.seconds,2592000);assert.equal(clock.recorded,true);
  const withdrawKey=randomUUID(),withdrawInput={expectedVersion:1,reason:'Synthetic changed decision'},withdrawn=await f.request(path+'/'+first.id+'/withdraw',withdrawInput,'master',withdrawKey);assert.equal(withdrawn.response.status,200,JSON.stringify(withdrawn.body));assert.equal(withdrawn.body.data.status,'withdrawn');assert.equal(withdrawn.body.data.version,2);assert.equal(withdrawn.body.data.requestedAt,first.requestedAt);assert.equal(withdrawn.body.data.reviewAfter,first.reviewAfter);
  const replacement=await f.request(path,input);assert.equal(replacement.response.status,201);assert.notEqual(replacement.body.data.id,first.id);assert.deepEqual((await f.request(path+'/'+first.id+'/withdraw',withdrawInput,'master',withdrawKey)).body,withdrawn.body);assert.equal((await f.request(path+'/'+first.id+'/withdraw',withdrawInput)).response.status,409);assert.equal((await f.request(path+'/'+replacement.body.data.id)).body.data.status,'pending');
  const page=(await f.request(path+'?limit=1')).body;assert.equal(page.data.length,1);assert.ok(page.nextCursor);assert.equal((await f.request(path+'?limit=1&after='+page.nextCursor)).body.data.length,1);
  assert.deepEqual((await f.pg.query('SELECT * FROM public.academies ORDER BY id')).rows,schools);assert.equal((await f.schoolRequest('people')).response.status,200);assert.equal((await f.pg.query('SELECT * FROM public.finance_journals')).rows.length,0);
  await assert.rejects(f.pg.exec("UPDATE platform_private.school_cancellation_requests SET requested_at=requested_at-interval '30 days',review_after=review_after-interval '30 days'"),/PLATFORM_HISTORY_IMMUTABLE/);await assert.rejects(f.pg.exec('DELETE FROM platform_private.school_cancellation_decisions'),/PLATFORM_HISTORY_IMMUTABLE/);
 }finally{await f.pg.close();}
});
