test('cancellation confirmation cannot retain a partial access restriction when audit receipt decision or school update is suppressed',async()=>{
 for(const [schema,table,condition]of[['platform_private','audit_events',"NEW.action='platform.subscription.cancellation.confirmed'"],['platform_private','request_receipts',"NEW.result#>>'{body,data,status}'='confirmed'"],['platform_private','school_cancellation_decisions',"NEW.decision='confirmed'"],['public','academies',"NEW.status='read_only' AND OLD.status='active'"]] as const){
  const f=await fixture();try{const old=await historicalCancellation(f),path='academies/'+f.a+'/subscription/cancellations/'+old.id+'/confirm',input={expectedVersion:1,expectedSubscriptionVersion:0,confirmAcademyId:f.a,reason:'Synthetic atomic restriction'},key=randomUUID(),before=(await f.pg.query('SELECT * FROM public.academies ORDER BY id')).rows;
   await f.pg.exec(`CREATE FUNCTION ${schema}.skip_confirmation_effect() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ${condition} THEN RETURN NULL;END IF;RETURN NEW;END $$;CREATE TRIGGER synthetic_skip BEFORE ${table==='academies'?'UPDATE':'INSERT'} ON ${schema}.${table} FOR EACH ROW EXECUTE FUNCTION ${schema}.skip_confirmation_effect()`);const r=await f.request(path,input,'master',key);assert.equal(r.response.status,503,JSON.stringify(r.body));assert.deepEqual((await f.pg.query('SELECT * FROM public.academies ORDER BY id')).rows,before);assert.equal((await f.pg.query('SELECT * FROM platform_private.school_cancellation_decisions')).rows.length,0);for(const t of['audit_events','request_receipts'])assert.equal((await f.pg.query('SELECT * FROM platform_private.'+t+' WHERE request_key=$1',[key])).rows.length,0);
   await f.pg.exec(`DROP TRIGGER synthetic_skip ON ${schema}.${table};DROP FUNCTION ${schema}.skip_confirmation_effect()`);assert.equal((await f.request(path,input,'master',key)).response.status,200);
  }finally{await f.pg.close();}
 }
});
