test('actual312to313 upgrade retains pending and withdrawn case clocks,receipts and broker identities before enabling owner confirmation',async()=>{
 const f=await fixture({throughSchema:312});try{
  const native=async(operation:string,input:unknown,key=randomUUID())=>(await f.pg.query<any>('SELECT platform_private.request($1,$2,$3,$4,$5::jsonb) r',[f.owner.user,f.owner.session,operation,key,JSON.stringify(input)])).rows[0].r;
  const input={academyId:f.a,expectedVersion:0,reason:'Synthetic retained request'},key=randomUUID(),first=await native('cancellations.request',input,key);await native('cancellations.withdraw',{academyId:f.a,cancellationId:first.body.data.id,expectedVersion:1,reason:'Synthetic retained withdrawal'});const pending=await native('cancellations.request',{...input,reason:'Synthetic still pending'});
  const sql="SELECT oid,proowner,proacl,prosecdef,proconfig FROM pg_proc WHERE oid=ANY(ARRAY['platform_private.request(uuid,uuid,text,uuid,jsonb)'::regprocedure,'platform_private.verify_school_cancellation_record()'::regprocedure]) ORDER BY oid",identity=(await f.pg.query(sql)).rows;
  const snapshot=async()=>{const rows=[];for(const t of['public.academies','platform_private.school_cancellation_requests','platform_private.audit_events','platform_private.request_receipts','platform_private.school_cancellation_cases'])rows.push((await f.pg.query('SELECT to_jsonb(x) r FROM '+t+' x ORDER BY to_jsonb(x)::text')).rows);rows.push((await f.pg.query("SELECT to_jsonb(x)-ARRAY['reviewed_subscription_version','operational_before','operational_after','academy_version_before','academy_version_after'] r FROM platform_private.school_cancellation_decisions x ORDER BY request_id")).rows);return rows;},before=await snapshot();
  await upgradeToCurrent(f.pg);assert.deepEqual(await snapshot(),before);assert.deepEqual((await f.pg.query(sql)).rows,identity);assert.equal((await f.pg.query('SELECT * FROM platform_private.school_cancellation_decisions WHERE reviewed_subscription_version IS NOT NULL OR operational_before IS NOT NULL OR operational_after IS NOT NULL OR academy_version_before IS NOT NULL OR academy_version_after IS NOT NULL')).rows.length,0);
  const path='academies/'+f.a+'/subscription/cancellations';assert.deepEqual((await f.request(path,{expectedVersion:0,reason:input.reason},'master',key)).body,first.body);assert.equal((await f.request(path+'/'+first.body.data.id)).body.data.status,'withdrawn');assert.equal((await f.request(path+'/'+pending.body.data.id)).body.data.reviewAfter,pending.body.data.reviewAfter);const r=await f.request(path+'/'+pending.body.data.id+'/confirm',{expectedVersion:1,expectedSubscriptionVersion:0,confirmAcademyId:f.a,reason:'Synthetic still too early'});assert.equal(r.response.status,409);assert.equal(r.body.error.code,'PLATFORM_CANCELLATION_WAITING_PERIOD');
 }finally{await f.pg.close();}
});
test('own-school subscription reads retain exact pinned prices and scoped cancellation history without platform notes or foreign school data',async()=>{
 const f=await fixture();try{
  const privateNote='Synthetic platform-only commercial note',amount='1234567890123456789',foreignAmount='9876543210987654321',plans=[];for(const [name,price]of[['Synthetic own plan',amount],['Synthetic foreign plan',foreignAmount]]){const r=await f.request('plans',{definition:{...definition,name,description:privateNote,amountMinor:price},reason:'Synthetic reference plan'});assert.equal(r.response.status,201);plans.push(r.body.data.id);}
  for(const [i,academy]of[f.a,f.b].entries())assert.equal((await f.request('academies/'+academy+'/subscription/assign',{expectedVersion:0,planId:plans[i],planVersion:1,startsAt:instant(-1),expiresAt:instant(30),reason:privateNote})).response.status,200);
  const cases='academies/'+f.a+'/subscription/cancellations',first=await f.request(cases,{expectedVersion:1,reason:privateNote});assert.equal(first.response.status,201);assert.equal((await f.request(cases+'/'+first.body.data.id+'/withdraw',{expectedVersion:1,reason:privateNote})).response.status,200);const second=await f.request(cases,{expectedVersion:1,reason:privateNote}),foreign=await f.request('academies/'+f.b+'/subscription/cancellations',{expectedVersion:1,reason:privateNote});
  const r=await f.schoolRequest('academy/subscription');assert.equal(r.response.status,200,JSON.stringify({body:r.body,errors:f.metrics.queryFailures}));assert.equal(r.response.headers.get('cache-control'),'no-store');assert.equal(r.body.data.academyId,f.a);assert.equal(r.body.data.planReference.referenceAmountMinor,amount);assert.equal(r.body.data.planReference.unitScale,2);assert.equal(r.body.data.latestCancellation.id,second.body.data.id);assert.equal(r.body.referencePriceOnly,true);assert.equal(r.body.paymentVerified,false);assert.equal(r.body.tuitionIncluded,false);assert.doesNotMatch(JSON.stringify(r.body),new RegExp(privateNote+'|'+foreignAmount+'|'+foreign.body.data.id+'|actor_user_id|session_id|request_key'));
  assert.equal((await f.schoolRequest('academy/subscription',{})).response.status,405);
  assert.equal((await f.request('plans/'+plans[0]+'/change',{expectedVersion:1,definition:{...definition,name:'Repriced reference',amountMinor:'555'},reason:'Synthetic new catalogue edition'})).response.status,200);assert.equal((await f.schoolRequest('academy/subscription')).body.data.planReference.referenceAmountMinor,amount);
  const page=(await f.schoolRequest('academy/subscription/cancellations?limit=1')).body;assert.equal(page.data[0].id,second.body.data.id);assert.ok(page.nextCursor);const next=new URLSearchParams({limit:'1',...page.nextCursor}),older=await f.schoolRequest('academy/subscription/cancellations?'+next);assert.equal(older.body.data[0].id,first.body.data.id);assert.equal(older.body.data[0].status,'withdrawn');assert.equal((await f.schoolRequest('academy/subscription/cancellations/'+foreign.body.data.id)).response.status,404);
  await f.pg.query("SELECT set_config('app.academy_id',$1,false)",[f.a]);await f.pg.exec('SET ROLE kavosh_runtime');try{const rows=(await f.pg.query('SELECT academy_id FROM public.academy_subscription_status')).rows;assert.deepEqual(rows,[{academy_id:f.a}]);assert.equal((await f.pg.query('SELECT * FROM public.academy_subscription_cancellations WHERE academy_id=$1',[f.b])).rows.length,0);await assert.rejects(f.pg.query('SELECT * FROM platform_private.school_cancellation_cases'),/permission denied/);}finally{await f.pg.exec('RESET ROLE');}
  const audit=(await f.pg.query("SELECT changes FROM public.audit_events WHERE action='academy.subscription.read'")).rows;assert.ok(audit.length>=4);assert.doesNotMatch(JSON.stringify(audit),new RegExp(amount+'|'+foreignAmount+'|'+privateNote));
 }finally{await f.pg.close();}
});
test('own subscription visibility is configurable for whole-academy human and bot roles,explicit denial wins and read-only schools retain reads',async()=>{
 const f=await fixture();try{
  const path='academy/subscription';for(const actor of['staff','manager','bot'])assert.equal((await f.schoolRequest(path,undefined,actor)).response.status,403);
  await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,'academy-subscription.view','allow')",[f.a,f.managerRole]);assert.equal((await f.schoolRequest(path,undefined,'manager')).response.status,403,'Hub-only permission cannot expose academy-wide billing terms');
  await f.pg.query("INSERT INTO public.role_permissions VALUES($1,$2,'academy-subscription.view','allow')",[f.a,f.policyRole]);for(const actor of['manager','bot'])assert.equal((await f.schoolRequest(path,undefined,actor)).response.status,200);
  await f.pg.query("UPDATE public.role_permissions SET effect='deny' WHERE role_id=$1 AND capability='academy-subscription.view'",[f.managerRole]);for(const actor of['manager','bot'])assert.equal((await f.schoolRequest(path,undefined,actor)).response.status,403);await f.pg.query("DELETE FROM public.role_permissions WHERE role_id=$1 AND capability='academy-subscription.view'",[f.managerRole]);
  assert.equal((await f.request('academies/'+f.a+'/change',{expectedVersion:1,status:'read_only',reason:'Synthetic read-only operation'})).response.status,200);for(const actor of['master','manager','bot'])assert.equal((await f.schoolRequest(path,undefined,actor)).response.status,200);
  await f.pg.query("DELETE FROM public.role_permissions WHERE role_id=$1 AND capability='academy-subscription.view'",[f.policyRole]);assert.equal((await f.schoolRequest(path,undefined,'manager')).response.status,403);assert.equal((await f.schoolRequest(path,undefined,'bot')).response.status,403);assert.equal((await f.schoolRequest(path,undefined,'foreignMaster')).response.status,401);
  assert.equal((await f.schoolRequest(path,{force:true})).response.status,403,'Read-only mutation gate remains before the endpoint');assert.equal((await f.schoolRequest(path+'?academyId='+f.b)).response.status,400);assert.equal((await f.schoolRequest(path+'/cancellations?afterId='+randomUUID())).response.status,400);
 }finally{await f.pg.close();}
});
